        /// <summary>
        /// 这一行到底有没有配音。key 形如 "Prologue1_7/~4ca079d5"。
        /// 先按完整键查，再退回**只看行号** —— 后者才是与游戏语音文件一致的口径。
        /// </summary>
        public static bool IsVoiced(string key)
        {
            if (string.IsNullOrEmpty(key)) return false;
            if (Voiced.Contains(key)) return true;
            int slash = key.IndexOf('/');
            string id = slash >= 0 ? key.Substring(slash + 1) : key;
            if (id.Length > 0 && id[0] == '~') id = id.Substring(1);
            return id.Length > 0 && VoicedIds.Contains(id);
        }
    }
